function validate([num1, num2, min_sum, max_sum]) {
  const whole = s => typeof s === 'string' && /^[1-9][0-9]*$/.test(s) && s.length <= 23;
  if (!whole(num1) || !whole(num2)) return 'num1 and num2 are positive whole numbers written without leading zeros.';
  const compare = (a, b) => a.length !== b.length ? a.length - b.length : a < b ? -1 : a > b ? 1 : 0;
  if (compare(num2, '1' + '0'.repeat(22)) > 0) return 'num2 is at most 10^22.';
  if (compare(num1, num2) > 0) return 'num1 must not be larger than num2.';
  if (!Number.isInteger(min_sum) || !Number.isInteger(max_sum)) return 'min_sum and max_sum are integers.';
  if (min_sum < 1 || max_sum > 400 || min_sum > max_sum) return 'Need 1 <= min_sum <= max_sum <= 400.';
  return null;
}

