function count(num1, num2, min_sum, max_sum) {
  const MOD = 1e9 + 7;

  function countUpTo(limit) {
    const memo = Array.from({ length: limit.length }, () => new Array(max_sum + 1).fill(-1));

    function dfs(pos, sum, tight) {
      if (sum > max_sum) {
        return 0;
      }
      if (pos === limit.length) {
        return sum >= min_sum ? 1 : 0;
      }
      if (!tight && memo[pos][sum] !== -1) {
        return memo[pos][sum];
      }
      const maxDigit = tight ? Number(limit[pos]) : 9;
      let ways = 0;
      for (let digit = 0; digit <= maxDigit; digit++) {
        ways = (ways + dfs(pos + 1, sum + digit, tight && digit === maxDigit)) % MOD;
      }
      if (!tight) {
        memo[pos][sum] = ways;
      }
      return ways;
    }

    return dfs(0, 0, true);
  }

  let firstSum = 0;
  for (const ch of num1) {
    firstSum += Number(ch);
  }
  const firstGood = firstSum >= min_sum && firstSum <= max_sum ? 1 : 0;
  return (countUpTo(num2) - countUpTo(num1) + firstGood + MOD) % MOD;
}

