function count(num1, num2, min_sum, max_sum) {
  // free[k][s] = exact number of k-digit strings (leading zeros allowed) whose digits add up to s.
  const free = [[1n]];
  for (let k = 1; k <= num2.length; k++) {
    const row = new Array(9 * k + 1).fill(0n);
    for (let s = 0; s < free[k - 1].length; s++) for (let d = 0; d <= 9; d++) row[s + d] += free[k - 1][s];
    free.push(row);
  }
  const good = s => s >= min_sum && s <= max_sum;
  // below(n) = how many x in [0, n) have a good digit sum: choose the first position where x drops below n.
  const below = n => {
    let total = 0n, prefix = 0;
    for (let i = 0; i < n.length; i++) {
      const rest = free[n.length - i - 1];
      for (let d = 0; d < Number(n[i]); d++)
        for (let s = 0; s < rest.length; s++) if (good(prefix + d + s)) total += rest[s];
      prefix += Number(n[i]);
    }
    return total;
  };
  const ownSum = [...num2].reduce((a, c) => a + Number(c), 0);
  const exact = below(num2) - below(num1) + (good(ownSum) ? 1n : 0n);
  return Number(exact % 1000000007n);
}

