function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const digits = len => String(int(1, 9)) + Array.from({ length: len - 1 }, () => int(0, 9)).join('');
  const notAbove = (a, b) => a.length !== b.length ? a.length < b.length : a <= b;
  if (size === 'small') {
    const high = int(1, 10 ** int(1, 6) - 1);
    const low = rand() < 0.15 ? high : int(1, high);
    const min_sum = int(1, 30);
    const max_sum = rand() < 0.1 ? 400 : Math.min(400, min_sum + int(0, 15));
    return [String(low), String(high), min_sum, max_sum];
  }
  const num2 = rand() < 0.2 ? '1' + '0'.repeat(22) : digits(22);
  let num1 = digits(int(1, 22));
  if (!notAbove(num1, num2)) num1 = num1.slice(1);
  if (num1 === '' || num1[0] === '0') num1 = '1';
  const min_sum = int(1, 150);
  const max_sum = int(min_sum, 400);
  return [num1, num2, min_sum, max_sum];
}
